// Pseudocode: handle a charge request with idempotency
function handleCharge(request) {
  key = request.headers['Idempotency-Key'] || generateRequestHash(request)

  // Fast path: check cache
  cached = redis.get(key)
  if (cached) {
    if (cached.status == 'completed') return fetchLedgerResponse(cached.ledgerId)
    if (cached.status == 'in-progress') return { status: 409, message: 'operation in progress' }
  }

  // Claim key atomically (set if not exists)
  ok = redis.setnx(key, {status: 'in-progress', ts: now()}, ttl=5min)
  if (!ok) return { status: 409, message: 'operation in progress' }

  // Persist to durable ledger (idempotent upsert keyed by idempotency key)
  ledgerId = db.transaction(() => {
    existing = db.selectLedgerByKey(key)
    if (existing) return existing.id
    return db.insertLedger({key, requestData, status: 'pending'})
  })

  // Call external processor and record result
  result = callExternalProcessor(request.paymentDetails)
  db.updateLedger(ledgerId, {status: result.ok ? 'succeeded' : 'failed', externalId: result.id})

  // Update cache with final pointer to ledger
  redis.set(key, {status: 'completed', ledgerId: ledgerId}, ttl=1h)

  return buildApiResponse(ledgerId)
}

