class CircuitBreaker {
  constructor(action, opts = {}) {
    this.action = action
    this.failureCount = 0
    this.state = 'CLOSED'
    this.failureThreshold = opts.failureThreshold || 5
    this.resetTimeout = opts.resetTimeout || 10000
    this.lastFailureAt = null
    this.maxHalfOpenAttempts = opts.maxHalfOpenAttempts || 2
    this.halfOpenAttempts = 0
  }

  async call(...args) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureAt > this.resetTimeout) {
        this.state = 'HALF_OPEN'
        this.halfOpenAttempts = 0
      } else {
        throw new Error('Circuit open')
      }
    }

    if (this.state === 'HALF_OPEN' && this.halfOpenAttempts >= this.maxHalfOpenAttempts) {
      throw new Error('Circuit half-open max trials reached')
    }

    try {
      const result = await this.action(...args)
      this._onSuccess()
      return result
    } catch (err) {
      this._onFailure()
      throw err
    }
  }

  _onSuccess() {
    this.failureCount = 0
    this.halfOpenAttempts = 0
    this.state = 'CLOSED'
  }

  _onFailure() {
    this.failureCount += 1
    this.lastFailureAt = Date.now()
    if (this.state === 'HALF_OPEN') {
      this.state = 'OPEN'
    } else if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN'
    }
    if (this.state === 'HALF_OPEN') this.halfOpenAttempts++
  }
}

